  self.step()?;
  self.references=self.references.checked_add(1).filter(|count|*count<=store::CHILD_RESTORE_MAXIMUM_REFERENCES).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"typed child binding exceeds its declared reference bound"))?;
  let root=self.children.root.as_deref().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"captured parent publication has no child root"))?;
  if root.len>store::CHILD_RESTORE_MAXIMUM_REFERENCES{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"captured child root exceeds the admitted parent reference bound"))}
