   control.begin_stage(root.len.checked_add(2).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"typed child resolution work overflow"))?)?;
   let mut selected=None;
   for entry in root.pages.iter().flatten().flat_map(|page|page.entries.iter().flatten()){
    control.step()?;
    if entry.captured.owner().slot==slot&&entry.captured.owner().child_id==fields.child_id{selected=Some(entry);break}
   }
   let entry=selected.ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"captured parent publication has no declared logical child"))?;
