   if target.artifact_id!=fields.artifact_id||target.dialect.artifact_kind!=fields.artifact_kind||target.dialect.standard!=fields.standard||target.dialect.subset!=fields.subset{
    return Err(ValueError::new(ValueRefusalKind::InvalidValue,"captured child target differs from its full declared parent reference"))
   }
   control.step()?;
   entry.captured.typed_child_read::<S>()?;
   control.step()?;
   control.checkpoint()?;
   Ok(())
  })
 }
